    [['A', A], ['B', B], ['C', Cc], ['D', D], ['A₁', A1], ['B₁', B1], ['C₁', C1], ['D₁', D1]].forEach(function (p) { s += '<text x="' + (p[1][0] + (p[1][0] < 150 ? -12 : 12)) + '" y="' + (p[1][1] + 26) + '" ' + TX + '>' + p[0] + '</text>'; });
